import unittest
class TestIterable(unittest.TestCase):
    def test_iter(self):
        sl = ShoppingList()
        sl.add("Milk", 1)
        sl.add("Bread", 2)
        items = []
        for item in sl:
            items.append(item)
        self.assertEqual(len(items), 2)
